cd /workspace/out && cat > analyze.pl <<'EOF'
#!/usr/bin/perl
use strict; use warnings;
my (%form, %qcount, $lines, $bad);
my (%qexamples);
open(my $fh, '<', 'corpus.txt') or die;
while (my $l = <$fh>) {
  chomp $l; next unless length $l;
  $lines++;
  my ($q, $body);
  if ($l =~ /^b'(.*)'$/) { $q = "single"; $body = $1; }
  elsif ($l =~ /^b"(.*)"$/) { $q = "double"; $body = $1; }
  else { print "UNPARSEABLE LINE: [$l]\n"; $bad++; next; }
  $qcount{$q}++;
  # tokenize
  my @toks; my $s = $body; my $ok=1;
  while (length $s) {
    if    ($s =~ s/^\\x([0-9a-fA-F]{2})//)  { push @toks, ["\\x$1", hex($1)]; }
    elsif ($s =~ s/^\\n//)  { push @toks, ['\\n', 0x0a]; }
    elsif ($s =~ s/^\\r//)  { push @toks, ['\\r', 0x0d]; }
    elsif ($s =~ s/^\\t//)  { push @toks, ['\\t', 0x09]; }
    elsif ($s =~ s/^\\\\//) { push @toks, ['\\\\', 0x5c]; }
    elsif ($s =~ s/^\\'//)  { push @toks, ["\\'", 0x27]; }
    elsif ($s =~ s/^\\"//)  { push @toks, ['\\"', 0x22]; }
    elsif ($s =~ s/^\\(.)//s){ push @toks, ["OTHERESC:\\$1", -1]; print "UNKNOWN ESCAPE \\$1 in [$l]\n"; $ok=0; }
    elsif ($s =~ s/^(.)//s) { push @toks, ["LIT:$1", ord($1)]; }
  }
  if (@toks != 16) { print "TOKENCOUNT=".scalar(@toks)." (expected 16) in [$l]\n"; $bad++; next; }
  next unless $ok;
  for my $t (@toks) {
    my ($form,$v) = @$t;
    $form =~ s/^\\x[0-9a-fA-F]{2}$/HEXESC/;
    $form =~ s/^LIT:.$/LITERAL/s;
    $form{$v}{$form}++;
    $form{$v}{"_rawhex_".( $t->[0] =~ /^\\x(.*)$/ ? $1 : "" )}++ if $t->[0] =~ /^\\x/;
  }
  # quote-case bookkeeping
  my $hasSQ = grep { $_->[1]==0x27 } @toks;
  my $hasDQ = grep { $_->[1]==0x22 } @toks;
  my $key = ($hasSQ?"SQ":"-").":".($hasDQ?"DQ":"-").":".$q;
  $qexamples{$key} ||= [];
  push @{$qexamples{$key}}, $l if @{$qexamples{$key}} < 4;
}
close $fh;
print "=== lines=$lines bad=$bad  quotes: ", join(", ", map {"$_=$qcount{$_}"} sort keys %qcount), "\n\n";
print "=== BYTE VALUE -> OBSERVED FORMS ===\n";
my @never;
for my $v (0..255) {
  if (!exists $form{$v}) { push @never, $v; next; }
  my @f = grep { !/^_rawhex_/ } sort keys %{$form{$v}};
  my @rh = map { s/^_rawhex_//r } grep { /^_rawhex_/ } sort keys %{$form{$v}};
  printf "0x%02x %-4s : %s  (n=%d)%s\n", $v, ($v>=32&&$v<127 ? "'".chr($v)."'" : ""),
    join("+", map {"$_ x$form{$v}{$_}"} @f), 0,
    (@rh ? "  hexdigits=[".join(",",@rh)."]" : "");
}
print "\nNEVER OBSERVED (".scalar(@never)."): ", join(" ", map {sprintf "0x%02x",$_} @never), "\n";
print "\n=== QUOTE CASES (SQ=contains 0x27, DQ=contains 0x22) ===\n";
for my $k (sort keys %qexamples) { printf "%-14s n_examples_shown=%d\n", $k, scalar @{$qexamples{$k}}; }
EOF
perl analyze.pl 2>&1 | head -300

