use strict; use warnings;
my %cnt; my %ex;
open(my $fh,'<','corpus.txt');
while (my $l=<$fh>) { chomp $l;
  my ($q,$body);
  if ($l=~/^b'(.*)'$/){$q="b'...'";$body=$1} elsif($l=~/^b"(.*)"$/){$q='b"..."';$body=$2//$1} else {next}
  # detect presence of raw 0x27 / 0x22 bytes by decoding
  my $s=$body; my ($sq,$dq,$esq,$edq)=(0,0,0,0);
  while(length $s){
    if($s=~s/^\\x[0-9a-fA-F]{2}//){}
    elsif($s=~s/^\\([nrt\\])//){}
    elsif($s=~s/^\\'//){$sq++;$esq++}
    elsif($s=~s/^\\"//){$dq++;$edq++}
    elsif($s=~s/^(.)//s){my $c=$1; $sq++ if $c eq "'"; $dq++ if $c eq '"';}
  }
  my $k=sprintf("has'=%s has\"=%s -> %s", $sq?"Y":"N", $dq?"Y":"N", $q);
  $k .= sprintf("  [' escaped=%s, \" escaped=%s]", $sq?($esq==$sq?"yes":($esq?"partial":"no")):"n/a", $dq?($edq==$dq?"yes":($edq?"partial":"no")):"n/a");
  $cnt{$k}++;
  push @{$ex{$k}}, $l if @{$ex{$k}||[]} < 3;
}
for my $k (sort keys %cnt){ printf "%-70s  n=%d\n", $k, $cnt{$k}; print "      $_\n" for @{$ex{$k}}; print "\n"; }
EOF
