use strict; use warnings;
my (%formcnt,%bytemap,$n,%hexcase,%qc,%ex,$badq,%adj);
open(my $fh,'<','corpus.txt');
while(my $l=<$fh>){ chomp $l; next unless length $l;
  my ($q,$body);
  if($l=~/^b'(.*)'$/){$q="SINGLE";$body=$1}
  elsif($l=~/^b"(.*)"$/){$q="DOUBLE";$body=$1}
  else{ next }
  $n++;
  my @t; my $s=$body;
  while(length $s){
    if($s=~s/^\\x([0-9a-fA-F]{2})//){ my $h=$1; $hexcase{ $h =~ /[A-F]/ ? "UPPER":"lower" }++;
        $formcnt{'\xHH'}++; push @t,[hex($h),'\xHH']; }
    elsif($s=~s/^\\n//){$formcnt{'\n'}++;push @t,[0x0a,'\n']}
    elsif($s=~s/^\\r//){$formcnt{'\r'}++;push @t,[0x0d,'\r']}
    elsif($s=~s/^\\t//){$formcnt{'\t'}++;push @t,[0x09,'\t']}
    elsif($s=~s/^\\\\//){$formcnt{'\\\\'}++;push @t,[0x5c,'\\\\']}
    elsif($s=~s/^\\'//){$formcnt{"\\'"}++;push @t,[0x27,"\\'"]}
    elsif($s=~s/^\\"//){$formcnt{'\"'}++;push @t,[0x22,'\"']}
    elsif($s=~s/^\\(.)//s){$formcnt{"UNKNOWN:\\$1"}++;push @t,[-1,"?"]}
    elsif($s=~s/^(.)//s){$formcnt{'literal'}++;push @t,[ord($1),'literal']}
  }
  if(@t!=16){print "BAD TOKEN COUNT ".scalar(@t).": $l\n"; next}
  $bytemap{$_->[0]}{$_->[1]}++ for @t;
  # adjacency: \xHH immediately followed by literal hex digit
  for my $i (0..$#t-1){ $adj{"hexesc_then_lit_hexdigit"}++ if $t[$i][1] eq '\xHH' && $t[$i+1][1] eq 'literal' && chr($t[$i+1][0]) =~ /^[0-9a-fA-F]$/; }
  my $sq = grep {$_->[0]==0x27} @t; my $dq = grep {$_->[0]==0x22} @t;
  my $k=($sq?"has_SQ":"no_SQ")."/".($dq?"has_DQ":"no_DQ")." => $q";
  $qc{$k}++; push @{$ex{$k}}, $l if @{$ex{$k}||[]}<5;
}
print "parsed lines = $n\n\n";
print "=== ESCAPE FORM INVENTORY (total occurrences) ===\n";
printf "  %-14s %d\n", $_, $formcnt{$_} for sort keys %formcnt;
print "\n=== HEX DIGIT CASE ===\n"; printf "  %s: %d\n",$_,$hexcase{$_} for sort keys %hexcase;
print "\n=== BYTES WITH MORE THAN ONE OBSERVED FORM ===\n";
for my $v (sort {$a<=>$b} keys %bytemap){ my @f=sort keys %{$bytemap{$v}};
  printf "  0x%02x : %s\n",$v,join(", ",map{"$_ x$bytemap{$v}{$_}"}@f) if @f>1; }
print "\n=== SPECIAL BYTES ===\n";
for my $v (0x00,0x07,0x08,0x09,0x0a,0x0b,0x0c,0x0d,0x1b,0x22,0x27,0x5c,0x7e,0x7f,0x80,0xa0,0xff){
  printf "  0x%02x : %s\n",$v, join(", ",map{"$_ x$bytemap{$v}{$_}"} sort keys %{$bytemap{$v}||{}}); }
print "\n=== ADJACENCY CHECK ===\n"; printf "  %s = %d\n",$_,$adj{$_} for sort keys %adj;
print "\n=== QUOTE SELECTION ===\n";
for my $k (sort keys %qc){ printf "  %-32s n=%d\n",$k,$qc{$k}; print "        $_\n" for @{$ex{$k}}; }
EOF
