cd /workspace/out && cat > lit.pl <<'EOF'
use strict; use warnings; my (%lit,%esc,%seen);
open(my $fh,'<','corpus.txt');
while(my $l=<$fh>){ chomp $l; my $body;
  if($l=~/^b'(.*)'$/){$body=$1} elsif($l=~/^b"(.*)"$/){$body=$1} else{next}
  my $s=$body;
  while(length $s){
    if($s=~s/^\\x([0-9a-fA-F]{2})//){$esc{hex $1}++;$seen{hex $1}++}
    elsif($s=~s/^\\n//){$esc{0x0a}++;$seen{0x0a}++}
    elsif($s=~s/^\\r//){$esc{0x0d}++;$seen{0x0d}++}
    elsif($s=~s/^\\t//){$esc{0x09}++;$seen{0x09}++}
    elsif($s=~s/^\\\\//){$esc{0x5c}++;$seen{0x5c}++}
    elsif($s=~s/^\\'//){$esc{0x27}++;$seen{0x27}++}
    elsif($s=~s/^(.)//s){$lit{ord $1}++;$seen{ord $1}++}
  }
}
my @never = grep {!$seen{$_}} 0..255;
my @litv = sort {$a<=>$b} keys %lit;
my @escv = sort {$a<=>$b} keys %esc;
sub rng { my @v=@_; my @o; my $i=0; while($i<@v){my $j=$i; $j++ while $j+1<@v && $v[$j+1]==$v[$j]+1;
  push @o, $i==$j ? sprintf("0x%02x",$v[$i]) : sprintf("0x%02x-0x%02x",$v[$i],$v[$j]); $i=$j+1} join(" ",@o) }
printf "total bytes decoded: %d\n", (eval{my $t=0;$t+=$_ for values %seen;$t});
print "NEVER OBSERVED: ", (@never? rng(@never) : "(none - all 256 values observed)"), "\n\n";
print "EVER LITERAL   : ", rng(@litv), "\n";
print "EVER ESCAPED   : ", rng(@escv), "\n";
print "\nBOTH literal & escaped: ", rng(grep {$lit{$_}&&$esc{$_}} 0..255), "\n";
print "ALWAYS literal        : ", rng(grep {$lit{$_}&&!$esc{$_}} 0..255), "\n";
print "ALWAYS escaped        : ", rng(grep {$esc{$_}&&!$lit{$_}} 0..255), "\n";
EOF
